    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] checkin = new long[n], checkout = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); checkin[i] = (long) in.nval;
            in.nextToken(); checkout[i] = (long) in.nval;
        }
        int[][] res = busiestDays(checkin, checkout);
        StringBuilder sb = new StringBuilder();
        for (int[] line : res) {
            for (int i = 0; i < line.length; i++) sb.append(line[i]).append(i + 1 < line.length ? " " : "");
            sb.append("\n");
        }
        System.out.print(sb);
    }
}
